using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class StockLevelTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 50);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-A", 30);
        _tracker.AddStock("SKU-A", 20);
        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-A", 100);
        _tracker.RemoveStock("SKU-A", 40);
        Assert.AreEqual(60, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_AllUnits_LeavesZero()
    {
        _tracker.AddStock("SKU-A", 25);
        _tracker.RemoveStock("SKU-A", 25);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExceedsLevel_Throws()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 11));
    }

    [TestMethod]
    public void RemoveStock_UnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("MISSING", 1));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", qty));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", qty));
    }
}

[TestClass]
public sealed class ReorderAlertTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void NeedsReorder_NoStock_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveDefaultThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 100);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", _tracker.ReorderThresholdDefault);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowDefaultThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", _tracker.ReorderThresholdDefault - 1);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_CustomThreshold_IsRespected()
    {
        _tracker.SetReorderThreshold("SKU-A", 5);
        _tracker.AddStock("SKU-A", 6);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        _tracker.RemoveStock("SKU-A", 1);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_ThresholdZero_OnlyTrueWhenEmpty()
    {
        _tracker.SetReorderThreshold("SKU-A", 0);
        _tracker.AddStock("SKU-A", 1);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        _tracker.RemoveStock("SKU-A", 1);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_ChangingDefaultThreshold_AffectsSkusWithoutCustom()
    {
        _tracker.ReorderThresholdDefault = 20;
        _tracker.AddStock("SKU-A", 15);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));

        _tracker.AddStock("SKU-A", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeValue_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-A", -1));
    }
}

[TestClass]
public sealed class WarehouseTransferTests
{
    private InventoryTracker _source = null!;
    private InventoryTracker _destination = null!;

    [TestInitialize]
    public void Setup()
    {
        _source = new InventoryTracker();
        _destination = new InventoryTracker();
    }

    [TestMethod]
    public void TransferTo_MovesStockBetweenTrackers()
    {
        _source.AddStock("SKU-A", 100);
        _source.TransferTo(_destination, "SKU-A", 30);

        Assert.AreEqual(70, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(30, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_AllUnits_EmptiesSource()
    {
        _source.AddStock("SKU-A", 50);
        _source.TransferTo(_destination, "SKU-A", 50);

        Assert.AreEqual(0, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(50, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_DestinationAlreadyHasStock_Accumulates()
    {
        _source.AddStock("SKU-A", 60);
        _destination.AddStock("SKU-A", 40);

        _source.TransferTo(_destination, "SKU-A", 20);

        Assert.AreEqual(40, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(60, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_ExceedsSourceStock_Throws()
    {
        _source.AddStock("SKU-A", 10);
        Assert.ThrowsException<InvalidOperationException>(
            () => _source.TransferTo(_destination, "SKU-A", 11));

        // Both trackers unchanged after failed transfer
        Assert.AreEqual(10, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(0, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
    {
        _source.AddStock("SKU-A", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _source.TransferTo(null!, "SKU-A", 5));
    }

    [TestMethod]
    public void TransferTo_MultipleTransfers_TrackCorrectly()
    {
        _source.AddStock("SKU-A", 100);

        _source.TransferTo(_destination, "SKU-A", 25);
        _source.TransferTo(_destination, "SKU-A", 25);

        Assert.AreEqual(50, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(50, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_TriggersReorderOnSource()
    {
        _source.SetReorderThreshold("SKU-A", 5);
        _source.AddStock("SKU-A", 10);
        Assert.IsFalse(_source.NeedsReorder("SKU-A"));

        _source.TransferTo(_destination, "SKU-A", 6);
        Assert.IsTrue(_source.NeedsReorder("SKU-A"));
    }
}

